/* TripMaster — i18n.js
   v1030 RC7: mechanical extraction. LANG_META, DEFAULT_LANG,
   activeLanguages() and TRANSLATIONS were moved verbatim out of the main
   inline script in index.html. t(), tf() and all DOM/state-dependent
   language functions remain in the main inline script. Loaded as a classic
   script after config.js.
   v1050-RC1: deterministic day intelligence, manual travel segments, planning and Access workflow keys added.
   v1040-RC2: Home dashboard, legacy Home migration, Trip Base and mobility keys added.
   v1040: 61 keys added per language for day deletion, undo, storage
   failure, trip details, activity location/end time/category, per-activity
   Access and the trip overview. field_note_ph and prefs_note were reworded.
   No key was renamed or removed. */

    /* ══════════════════════════════════════════════════════════════════
       I18N-001 (v1030): Language Foundation
       ──────────────────────────────────────────────────────────────────
       Central localization section. Additive only:
         - No existing function is renamed or moved.
         - No storage key changes. The only data-model addition is
           settings.language, defaulted and validated by normalizeSettings().
         - App-owned STATIC UI strings only. User-created content (trip
           names, activity titles, notes, addresses, backup payloads) is
           never passed through t() and is never rewritten.
       Active languages: he (default), en, ar, ru, es, pt, am.
       Amharic: am -> am-ET, LTR. v3000 activates a complete 970-key UI
       translation set. The copy is beta and should still receive native
       linguistic review before a general-availability launch.
       ══════════════════════════════════════════════════════════════════ */

    const LANG_META = Object.freeze({
      he: { lang: "he",    dir: "rtl", label: "עברית",    active: true  },
      en: { lang: "en",    dir: "ltr", label: "English",   active: true  },
      ar: { lang: "ar",    dir: "rtl", label: "العربية",   active: true  },
      ru: { lang: "ru",    dir: "ltr", label: "Русский",   active: true  },
      es: { lang: "es",    dir: "ltr", label: "Español",   active: true  },
      pt: { lang: "pt-BR", dir: "ltr", label: "Português", active: true  },
      // v3000: complete Amharic UI table. LTR / am-ET. Copy is beta-quality
      // pending native linguistic review, but key parity and runtime behavior
      // are fully gated like every other active language.
      am: { lang: "am-ET", dir: "ltr", label: "አማርኛ",      active: true  }
    });

    const DEFAULT_LANG = "he";

    function activeLanguages() {
      return Object.keys(LANG_META).filter((c) => LANG_META[c].active);
    }

