  "about_title": "ℹ️ ስለ TripMaster",
  "about_privacy_h": "🔒 ግላዊነት",
  "about_privacy_1": "የጉዞ ውሂብዎ በነባሪ በዚህ መሣሪያ ላይ በአካባቢው ይቀመጣል።",
  "about_privacy_2": "ለአሁኑ መለያ ወይም የደመና ማመሳሰል የለም። TripMaster AI ሲጠቀሙ፣ ጥያቄዎን ለመመለስ የሚያስፈልገው የተጣራ የጉዞ አውድ ብቻ ወደ AI አገልግሎት ይላካል።",
  "about_beta_h": "🧪 እንዴት እንደሚፈተሽ (Beta)",
  "about_beta_1": "በተለያዩ ቀናት እንቅስቃሴዎችን ጨምሩ፣ አርትዑ እና ሰርዙ",
  "about_beta_2": "በጉዞዎች መካከል ይቀያይሩ እና ውሂቡ በትክክለኛው ቦታ መቆየቱን ያረጋግጡ",
  "about_beta_3": "የአውሮፕላን ሁነታን ያብሩ እና መተግበሪያው እንደሚከፈት ያረጋግጡ",
  "about_beta_4": "ምትኬ ይፍጠሩ፣ ይመልሱት እና ሁሉም ነገር መመለሱን ያረጋግጡ",
  "about_beta_5": "የተበላሸ፣ እንግዳ ወይም የጎደለ ነገር ካዩ፣ ይህንን በትክክል ማወቅ እንፈልጋለን",
  "about_feedback_h": "💬 አስተያየት እና የስህተት ሪፖርት",
